  /**
   * Returns whether the feature has been set
   */
  override eIsSet(feature: EStructuralFeature): boolean {
    const featureID = this.eClass().getFeatureID(feature);
    switch (featureID) {
      case MapLibreSettingsImpl.DATASOURCE_ID:
        return this._datasourceId !== undefined;
      case MapLibreSettingsImpl.STYLE_URL:
        return this._styleUrl !== "https://tiles.openfreemap.org/styles/liberty";
      case MapLibreSettingsImpl.DARK_STYLE_URL:
        return this._darkStyleUrl !== "https://tiles.openfreemap.org/styles/dark";
      case MapLibreSettingsImpl.RASTER_URL:
        return this._rasterUrl !== "";
      case MapLibreSettingsImpl.RASTER_LAYERS:
        return this._rasterLayers !== "";
      case MapLibreSettingsImpl.RASTER_OPACITY:
        return this._rasterOpacity !== 1;
      case MapLibreSettingsImpl.RASTER_ATTRIBUTION:
        return this._rasterAttribution !== "";
      case MapLibreSettingsImpl.RASTER_INVERT_DARK:
        return this._rasterInvertDark !== true;
      case MapLibreSettingsImpl.ATTRIBUTION:
        return this._attribution !== "";
      case MapLibreSettingsImpl.ATTRIBUTION_COMPACT:
        return this._attributionCompact !== true;
      case MapLibreSettingsImpl.CENTER_LAT:
        return this._centerLat !== 50.9271;
      case MapLibreSettingsImpl.CENTER_LON:
        return this._centerLon !== 11.5892;
      case MapLibreSettingsImpl.ZOOM:
        return this._zoom !== 15;
      case MapLibreSettingsImpl.PITCH:
        return this._pitch !== 50;
      case MapLibreSettingsImpl.BEARING:
        return this._bearing !== -20;
      case MapLibreSettingsImpl.INTERACTIVE:
        return this._interactive !== true;
      case MapLibreSettingsImpl.BUILDINGS:
        return this._buildings !== true;
      case MapLibreSettingsImpl.BUILDING_COLOR:
        return this._buildingColor !== "#d6d0c4";
      case MapLibreSettingsImpl.BUILDING_OPACITY:
        return this._buildingOpacity !== 0.85;
      case MapLibreSettingsImpl.BUILDING_SOURCE_LAYER:
        return this._buildingSourceLayer !== "building";
      case MapLibreSettingsImpl.TERRAIN_URL:
        return this._terrainUrl !== "";
      case MapLibreSettingsImpl.TERRAIN_ENCODING:
        return this._terrainEncoding !== "terrarium";
      case MapLibreSettingsImpl.TERRAIN_EXAGGERATION:
        return this._terrainExaggeration !== 1.5;
      case MapLibreSettingsImpl.SKY:
        return this._sky !== true;
      case MapLibreSettingsImpl.SELECTION_COLOR:
        return this._selectionColor !== "#ffb300";
      case MapLibreSettingsImpl.THING_LAYERS:
        return this._thingLayers !== undefined && !this._thingLayers.isEmpty();
      case MapLibreSettingsImpl.GEO_JSON_LAYERS:
        return this._geoJsonLayers !== undefined && !this._geoJsonLayers.isEmpty();
      case MapLibreSettingsImpl.SERVICES:
        return this._services !== undefined && !this._services.isEmpty();
      case MapLibreSettingsImpl.WMS_LAYERS:
        return this._wmsLayers !== undefined && !this._wmsLayers.isEmpty();
      case MapLibreSettingsImpl.MODEL_LAYERS:
        return this._modelLayers !== undefined && !this._modelLayers.isEmpty();
      default:
        return super.eIsSet(feature);
    }
  }

